python - <<'PY'
import time, pathlib, re
p=pathlib.Path('/tmp/flutter_run.log')
for i in range(60):
    if p.exists():
        t=p.read_text(errors='ignore')
        m=re.search(r'Dart VM service.*?listening on (http://[^\s/]+/[A-Za-z0-9_=\-]+)', t)
        if m:
            print('FOUND', m.group(1));
            break
    time.sleep(2)
else:
    print('not found')
